#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.277777685, -0.35694436, 2.9999999984209325e-08], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.06944446499999998, 'zmax': 0.06944446500000001, 'profiles': [{'outer': [[-0.27777764, -0.059717949999999964], [-0.27248764000000003, -0.03314908999999999], [-0.25743985, -0.010615579999999958], [-0.23490638000000003, 0.004432209999999992], [-0.20832896, 0.009722270000000033], [-0.18176013000000002, 0.004432240000000032], [-0.15922663, -0.010615549999999974], [-0.14417884, -0.03314906000000001], [-0.13888880402684223, -0.05971779932730312], [-0.13359880000000002, -0.033149119999999976], [-0.11855102000000002, -0.010615579999999958], [-0.09601754000000001, 0.004432180000000008], [-0.06944016000000001, 0.009722239999999993], [-0.042871300000000015, 0.004432209999999992], [-0.020337780000000017, -0.010615579999999958], [-0.005290000000000016, -0.03314908999999999], [9.999999984209322e-09, -0.059717849551193435], [0.005290019999999984, -0.03314908999999999], [0.020337789999999984, -0.010615549999999974], [0.042871329999999985, 0.004432240000000032], [0.06944865999999998, 0.009722270000000033], [0.09601751999999998, 0.004432240000000032], [0.11855101999999998, -0.010615549999999974], [0.1335988, -0.03314906000000001], [0.138888818959746, -0.05971781432677959], [0.14417881, -0.033149119999999976], [0.15922657999999998, -0.010615609999999998], [0.18176008999999999, 0.004432180000000008], [0.20833743, 0.009722210000000009], [0.23490631999999997, 0.004432180000000008], [0.25743982, -0.010615579999999958], [0.27248761, -0.03314908999999999], [0.27777764, -0.059717980000000004], [0.27248761, -0.08629529999999996], [0.25743982, -0.10882881], [0.23490629999999998, -0.12387661999999999], [0.20833743999999998, -0.12916666], [0.18176009999999998, -0.12387661999999999], [0.1592266, -0.10882883999999998], [0.14417881999999999, -0.08629533], [0.1388888010430472, -0.05971811572090189], [0.1335988, -0.08629524], [0.11855103999999998, -0.10882877999999996], [0.09601749999999998, -0.12387655999999997], [0.06944863999999998, -0.12916659999999996], [0.04287129999999999, -0.12387655999999997], [0.020337809999999984, -0.10882881], [0.005290019999999984, -0.08629526999999998], [1.0000011272022787e-08, -0.0597180504808479], [-0.005290000000000016, -0.08629529999999996], [-0.020337760000000017, -0.10882881], [-0.04287127000000002, -0.12387659000000001], [-0.06944016000000001, -0.12916663], [-0.09601751000000001, -0.12387659000000001], [-0.11855102000000002, -0.10882883999999998], [-0.13359877, -0.08629533], [-0.13888881597119299, -0.05971810072090057], [-0.14417881000000002, -0.08629526999999998], [-0.15922660000000002, -0.10882877999999996], [-0.1817601, -0.12387655999999997], [-0.20832896, -0.12916663], [-0.23490635, -0.12387659000000001], [-0.25743982000000004, -0.10882881], [-0.27248761, -0.08629529999999996]], 'holes': []}, {'outer': [[-0.18799543000000002, 0.10882879000000001], [-0.16546193, 0.12387659000000001], [-0.13888454000000003, 0.12916663], [-0.11231574000000001, 0.12387659000000001], [-0.08978221000000002, 0.10882884000000001], [-0.07473442000000001, 0.08629531000000001], [-0.06944440201345506, 0.05972651033686107], [-0.06415442000000002, 0.08629528000000003], [-0.049106600000000014, 0.10882882000000002], [-0.026573080000000016, 0.12387659000000001], [4.24999999998421e-06, 0.12916664000000003], [0.026573109999999983, 0.12387661000000003], [0.04910660999999998, 0.10882884000000001], [0.06415439999999999, 0.08629534], [0.06944441298657873, 0.05972648522431679], [0.07473442999999999, 0.08629528000000003], [0.08978219999999998, 0.10882879000000001], [0.11231573999999998, 0.12387661000000003], [0.13889306999999998, 0.12916666000000002], [0.16546192999999998, 0.12387662000000002], [0.18799543, 0.10882884000000001], [0.20304322, 0.08629534], [0.20833325, 0.05972645000000004], [0.20304322, 0.03314913000000003], [0.18799544999999998, 0.010615619999999992], [0.16546191, -0.0044321900000000025], [0.13889306999999998, -0.009722229999999998], [0.11231571999999998, -0.0044321900000000025], [0.08978221999999998, 0.010615570000000019], [0.07473442999999999, 0.03314910000000004], [0.06944440701437431, 0.05972638475950595], [0.06415439999999999, 0.03314910000000004], [0.049106629999999984, 0.010615590000000008], [0.026573119999999985, -0.0044321900000000025], [4.2599999999842095e-06, -0.009722229999999998], [-0.026573110000000014, -0.0044321900000000025], [-0.04910663000000002, 0.010615570000000019], [-0.06415442000000002, 0.03314910000000004], [-0.06944440798566923, 0.05972635963918444], [-0.07473442000000001, 0.03314910000000004], [-0.08978221000000002, 0.010615590000000008], [-0.11231574000000001, -0.0044321900000000025], [-0.13888457, -0.009722259999999983], [-0.16546196000000002, -0.004432219999999987], [-0.18799543000000002, 0.010615570000000019], [-0.20304322000000002, 0.03314907], [-0.20833322, 0.05972639000000002], [-0.20304322000000002, 0.08629528000000003]], 'holes': []}], 'simplify_tolerance': 0.00011111105600000001, 'sketch_entity_count': 112}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
